document.addEventListener('DOMContentLoaded', () => {
  initMarquees();
  initNavbarHeightVar();
  initAosElements();
  initBackgroundVideoReady();
  initReelTransition();
  initContactForm();
  initShortProjectVideosAutoplay();
});

/**Infinite horizontal marquee ticker */
function initMarquees() {
  const wrappers = document.querySelectorAll('.marquee-wrapper');
  for (const wrapper of wrappers) {
    const track = wrapper.querySelector('.marquee-track');
    if (!track) continue;

    const speed = Number(wrapper.dataset.marqueeSpeed) || 60;
    const direction = wrapper.dataset.marqueeDirection || 'left';
    const pauseOnHover = wrapper.dataset.marqueePause === 'true';

    let isPaused = false;
    let offset = 0;
    let lastTime = null;
    let baseWidth = 0;
    let lastObservedWidth = 0;
    let observedEl = null;

    for (const child of Array.from(track.children)) {
      child.dataset.marqueeOriginal = '';
    }

    const rebuildClones = (entries) => {
      if (entries && entries.length > 0) {
        const w = entries[0].contentRect.width;
        if (Math.abs(w - lastObservedWidth) < 1) return;
      }

      Array.from(track.children)
        .filter((el) => !('marqueeOriginal' in el.dataset))
        .forEach((el) => el.remove());

      const originals = Array.from(track.children);
      const trackWidth = track.scrollWidth;
      const wrapperWidth = wrapper.offsetWidth;
      const useViewport = trackWidth > 0 && wrapperWidth <= trackWidth;
      const fillTarget = useViewport ? window.innerWidth : wrapperWidth;

      if (trackWidth > 0) {
        const copies = Math.ceil(fillTarget / trackWidth) + 1;
        for (let i = 0; i < copies; i++) {
          for (const item of originals) {
            const clone = item.cloneNode(true);
            clone.removeAttribute('data-marquee-original');
            track.appendChild(clone);
          }
        }
      }

      baseWidth = trackWidth;
      offset = baseWidth > 0 ? offset % baseWidth : 0;
      if (direction === 'right' && offset >= 0) offset -= baseWidth;
      lastTime = null;
      lastObservedWidth = useViewport ? document.documentElement.clientWidth : wrapper.offsetWidth;

      const targetToObserve = useViewport ? document.documentElement : wrapper;
      if (targetToObserve !== observedEl) {
        if (observedEl) resizeObserver.unobserve(observedEl);
        resizeObserver.observe(targetToObserve);
        observedEl = targetToObserve;
      }
    };

    const resizeObserver = new ResizeObserver(rebuildClones);

    const step = (timestamp) => {
      if (!lastTime) lastTime = timestamp;
      const dt = (timestamp - lastTime) / 1000;
      lastTime = timestamp;

      if (!isPaused && baseWidth > 0) {
        offset += (direction === 'left' ? -1 : 1) * speed * dt;
        if (direction === 'left' && offset <= -baseWidth) offset += baseWidth;
        if (direction === 'right' && offset >= 0) offset -= baseWidth;
        track.style.transform = `translate3d(${offset}px, 0, 0)`;
      }
      window.requestAnimationFrame(step);
    };

    if (pauseOnHover) {
      wrapper.addEventListener('mouseenter', () => { isPaused = true; });
      wrapper.addEventListener('mouseleave', () => { isPaused = false; });
    }

    rebuildClones();
    window.requestAnimationFrame(step);
    if (document.readyState !== 'complete') {
      window.addEventListener('load', () => rebuildClones(), { once: true });
    }
  }
}

/** Keeps --nav-h CSS custom property synced with fixed navbar height */
function initNavbarHeightVar() {
  const nav = document.querySelector('.navbar.fixed-top');
  if (!nav) return;

  const updateNavHeight = () => {
    document.documentElement.style.setProperty('--nav-h', `${nav.offsetHeight}px`);
  };

  updateNavHeight();
  window.addEventListener('resize', updateNavHeight, { passive: true });
  window.addEventListener('load', updateNavHeight, { once: true });
  if ('ResizeObserver' in window) {
    new ResizeObserver(updateNavHeight).observe(nav);
  }
}

/** Lightweight IntersectionObserver entrance animations for [data-aos] */
function initAosElements() {
  const elements = Array.from(document.querySelectorAll('[data-aos]'));
  if (!elements.length) return;

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  for (const el of elements) {
    const duration = parseInt(el.getAttribute('data-aos-duration'), 10);
    const delay = parseInt(el.getAttribute('data-aos-delay'), 10);
    if (!Number.isNaN(duration)) el.style.setProperty('--aos-duration', `${duration}ms`);
    if (!Number.isNaN(delay)) el.style.setProperty('--aos-delay', `${delay}ms`);
  }

  const reveal = (el) => {
    el.classList.add('aos-in');
    const duration = parseFloat(el.style.getPropertyValue('--aos-duration')) || 400;
    const delay = parseFloat(el.style.getPropertyValue('--aos-delay')) || 0;
    window.setTimeout(() => {
      el.classList.add('aos-done');
    }, duration + delay + 100);
  };

  if (!reducedMotion && 'IntersectionObserver' in window) {
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            reveal(entry.target);
            observer.unobserve(entry.target);
          }
        }
      },
      { rootMargin: '0px 0px -80px 0px', threshold: 0 }
    );

    for (const el of elements) observer.observe(el);
    window.setTimeout(() => {
      for (const el of elements) {
        if (!el.classList.contains('aos-in')) reveal(el);
      }
    }, 3000);
  } else {
    for (const el of elements) reveal(el);
  }
}

/** Fades in background video once first frame is ready */
function initBackgroundVideoReady() {
  const video = document.querySelector('.page-video-bg video');
  if (!video) return;

  let marked = false;
  const markReady = () => {
    if (!marked) {
      marked = true;
      video.classList.add('is-video-ready');
    }
  };

  if (video.readyState >= 2) {
    markReady();
  } else {
    video.addEventListener('loadeddata', markReady, { once: true });
    video.addEventListener('playing', markReady, { once: true });
    video.addEventListener('canplay', markReady, { once: true });
    window.setTimeout(markReady, 2500);
  }
}

/**
 * Single-video morph transition between full-bleed background and 16:9 reel player.
 * Uses the same <video id="bgVideo"> element in both states so playback never
 * seeks, stutters, or drifts out of sync, and supports both Zoom In and Zoom Out.
 */
function initReelTransition() {
  const body = document.body;
  if (!body.classList.contains('has-page-video')) return;

  const videoBg = document.querySelector('.page-video-bg');
  const bgVideo = document.getElementById('bgVideo') || (videoBg && videoBg.querySelector('video'));
  const reelTarget = document.getElementById('reelTarget') || document.querySelector('.reel-player');
  if (!videoBg || !bgVideo || !reelTarget) return;

  const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  const MORPH_DURATION_MS = 480;
  let morphTimer = null;

  const playSafe = () => {
    if (bgVideo.paused) {
      const p = bgVideo.play();
      if (p && typeof p.catch === 'function') p.catch(() => {});
    }
  };

  const clearMorphTimer = () => {
    if (morphTimer !== null) {
      window.clearTimeout(morphTimer);
      morphTimer = null;
    }
  };

  const getTargetRect = () => {
    const rect = reelTarget.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0 ? rect : null;
  };

  const applyRect = (rect) => {
    videoBg.style.top = `${rect.top}px`;
    videoBg.style.left = `${rect.left}px`;
    videoBg.style.width = `${rect.width}px`;
    videoBg.style.height = `${rect.height}px`;
  };

  const applyFullscreenRect = () => {
    videoBg.style.top = '0px';
    videoBg.style.left = '0px';
    videoBg.style.width = `${window.innerWidth}px`;
    videoBg.style.height = `${window.innerHeight}px`;
  };

  const openReel = () => {
    if (body.classList.contains('is-reel-mode')) return;
    const targetRect = getTargetRect();
    if (!targetRect) return;

    clearMorphTimer();

    // Start from current rendered rect (either fullscreen or mid-zoom-out)
    const currentRect = videoBg.getBoundingClientRect();
    videoBg.classList.remove('is-resizing');
    videoBg.classList.add('is-morphing');
    applyRect(currentRect);

    // Force layout flush so the transition animates from currentRect -> targetRect
    void videoBg.offsetWidth;

    body.classList.remove('is-reel-closing');
    body.classList.add('is-reel-mode');
    videoBg.setAttribute('aria-hidden', 'false');
    bgVideo.removeAttribute('aria-hidden');
    bgVideo.tabIndex = 0;

    playSafe();
    applyRect(targetRect);

    const finalizeOpen = () => {
      morphTimer = null;
      if (!body.classList.contains('is-reel-mode')) return;
      bgVideo.controls = true;
    };

    if (reducedMotionQuery.matches) {
      finalizeOpen();
    } else {
      morphTimer = window.setTimeout(finalizeOpen, MORPH_DURATION_MS);
    }
  };

  const closeReel = () => {
    if (!body.classList.contains('is-reel-mode')) return;

    clearMorphTimer();

    // Hide native controls before zooming out so control bar doesn't stretch
    bgVideo.controls = false;
    bgVideo.tabIndex = -1;
    bgVideo.setAttribute('aria-hidden', 'true');
    bgVideo.playbackRate = 1;
    bgVideo.muted = true;
    playSafe();

    // Capture current player rect (or mid-zoom-in rect)
    const currentRect = videoBg.getBoundingClientRect();
    videoBg.classList.remove('is-resizing');
    videoBg.classList.add('is-morphing');
    applyRect(currentRect);

    // Force layout flush so the transition animates from currentRect -> fullscreen
    void videoBg.offsetWidth;

    body.classList.remove('is-reel-mode');
    body.classList.add('is-reel-closing');
    applyFullscreenRect();

    const finalizeClose = () => {
      morphTimer = null;
      if (body.classList.contains('is-reel-mode')) return;
      body.classList.remove('is-reel-closing');
      videoBg.classList.remove('is-morphing', 'is-resizing');
      videoBg.removeAttribute('style');
      videoBg.setAttribute('aria-hidden', 'true');
    };

    if (reducedMotionQuery.matches) {
      finalizeClose();
    } else {
      morphTimer = window.setTimeout(finalizeClose, MORPH_DURATION_MS);
    }
  };

  // Sync player position on viewport resize while in reel mode
  const syncOnResize = () => {
    if (body.classList.contains('is-reel-mode') && morphTimer === null) {
      const targetRect = getTargetRect();
      if (!targetRect) return;
      videoBg.classList.add('is-resizing');
      applyRect(targetRect);
      void videoBg.offsetWidth;
      videoBg.classList.remove('is-resizing');
    } else if (body.classList.contains('is-reel-closing')) {
      applyFullscreenRect();
    }
  };

  window.addEventListener('resize', syncOnResize, { passive: true });
  if ('ResizeObserver' in window) {
    new ResizeObserver(syncOnResize).observe(reelTarget);
  }

  // Click handler: Hero button opens reel; clicking outside video in reel mode closes it
  document.addEventListener('click', (e) => {
    const heroBtn = e.target.closest('.hero-section a.btn, #reelTrigger');
    if (heroBtn && !(e.metaKey || e.ctrlKey || e.shiftKey || e.altKey)) {
      e.preventDefault();
      if (body.classList.contains('is-reel-mode')) {
        closeReel();
      } else {
        openReel();
      }
      return;
    }

    if (body.classList.contains('is-reel-mode')) {
      const clickedInsidePlayer = e.target.closest('.page-video-bg');
      const clickedNavOrFooter = e.target.closest('.navbar, footer');
      if (!clickedInsidePlayer && !clickedNavOrFooter) {
        closeReel();
      }
    }
  });

  // Escape key closes reel mode (unless user is exiting browser native fullscreen)
  document.addEventListener('keydown', (e) => {
    if ((e.key === 'Escape' || e.key === 'Esc') && !document.fullscreenElement) {
      closeReel();
    }
  });

  // Support #reel hash on initial load
  const checkReelHash = () => {
    if (window.location.hash === '#reel') {
      if (window.history.replaceState) {
        window.history.replaceState(null, '', window.location.pathname);
      }
      window.setTimeout(openReel, 120);
    }
  };

  checkReelHash();
  window.addEventListener('load', checkReelHash, { once: true });
}

/** Web3Forms AJAX submission for Contact page */
function initContactForm() {
  const form = document.getElementById('contactForm');
  if (!form) return;

  const topicInput = form.querySelector('#topic');
  const statusEl = document.getElementById('contactStatus');
  const submitBtn = form.querySelector('[type="submit"]');
  let isSubmitting = false;

  const setStatus = (message, state) => {
    if (!statusEl) return;
    statusEl.textContent = message;
    statusEl.classList.remove('d-none', 'text-primary', 'text-danger', 'text-body-tertiary');
    statusEl.classList.add(
      state === 'ok' ? 'text-primary' : state === 'error' ? 'text-danger' : 'text-body-tertiary'
    );
  };

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    if (isSubmitting) return;

    if (!form.checkValidity()) {
      form.classList.add('was-validated');
      setStatus('Please fill in the required fields.', 'error');
      return;
    }

    const name = (form.querySelector('#name')?.value || '').trim();
    const email = (form.querySelector('#email')?.value || '').trim();
    const message = (form.querySelector('#message')?.value || '').trim();
    const topic = (topicInput?.value || '').trim() || 'General inquiry';

    const payload = {
      access_key: 'e6bbe42b-84ec-4652-8e7d-5cf01ab403dd',
      subject: `Contact Form Mail: ${topic}`,
      from_name: name || 'Website visitor',
      name,
      email,
      topic,
      message,
    };

    isSubmitting = true;
    if (submitBtn) submitBtn.disabled = true;
    setStatus('Sending…', 'pending');

    fetch('https://api.web3forms.com/submit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify(payload),
    })
      .then((res) => res.json().catch(() => ({ success: res.ok })))
      .then((data) => {
        if (!data.success) throw new Error(data.message || 'Send failed');
        form.reset();
        form.classList.remove('was-validated');
        setStatus('Thanks — your message was sent.', 'ok');
      })
      .catch(() => {
        setStatus('Something went wrong. Please try again.', 'error');
      })
      .finally(() => {
        isSubmitting = false;
        if (submitBtn) submitBtn.disabled = false;
      });
  });
}

/** Autoplays short (<= 12s) muted videos inside project breakdowns when visible */
function initShortProjectVideosAutoplay() {
  const videos = Array.from(document.querySelectorAll('.pf-proj-media video'));
  if (!videos.length) return;

  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    for (const v of videos) v.dataset.autoplayChecked = 'off';
    return;
  }

  const playSafe = (v) => {
    if (v.paused) {
      const p = v.play();
      if (p && typeof p.catch === 'function') p.catch(() => {});
    }
  };

  const setupVideo = (v) => {
    if (v.dataset.autoplayChecked) return;
    const duration = v.duration;
    if (!Number.isFinite(duration) || duration > 12) {
      v.dataset.autoplayChecked = 'skipped';
      return;
    }

    v.dataset.autoplayChecked = 'on';
    v.autoplay = true;
    v.loop = true;
    v.muted = true;

    if ('IntersectionObserver' in window) {
      new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            if (entry.isIntersecting) {
              playSafe(v);
            } else if (!v.paused) {
              v.pause();
            }
          }
        },
        { threshold: 0.25 }
      ).observe(v);
    } else {
      playSafe(v);
    }
  };

  for (const v of videos) {
    if (v.readyState >= 1) {
      setupVideo(v);
    } else {
      v.addEventListener('loadedmetadata', () => setupVideo(v), { once: true });
    }
  }
}
